//! Checks traced object regions against QuPath's own output.
//!
//! Fixture generated by `parity/java/ObjectFilters.java` via
//! `./parity/record.sh`, recorded through
//! `RoiLabeling.getFilledPolygonROIs(ipNucleusLabels, Wand.FOUR_CONNECTED)` —
//! the call that turns flooded basins into candidate objects. Needs no slide.
//!
//! The input fed in here is the **recorded** label image, so a failure is about
//! the tracing and cannot be about the flood that produced it. `qupath-pipeline`
//! checks the filters that consume these regions against the same file.
//!
//! QuPath returns polygons and this returns filled masks, so the comparison is
//! made on the mask each polygon rasterises to — which is what every later step
//! actually reads. Region numbers are compared exactly rather than up to a
//! permutation: they follow the raster order of each region's first traced
//! pixel, and the filters iterate them in that order.

use qupath_watershed::RegionTracer;

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/ObjectFilters.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn ints(text: &str) -> Vec<u32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("integer"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

#[test]
fn matches_qupath_filled_polygon_rois() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));
    let (cases, _) = between(&text, "\"cases\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut objects = 0u32;
    let mut at = 0usize;
    // One tracer across every case on purpose: a stamp buffer left dirty by a
    // previous shape would show up here and nowhere else.
    let mut tracer = RegionTracer::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (_, next) = scalar(cases, "threshold", next);
        let (expected_count, next) = scalar(cases, "roiCount", next);
        let (overlaps, next) = scalar(cases, "overlaps", next);
        let (_, next) = scalar(cases, "hasBackgroundMask", next);
        let (labels_text, next) = between(cases, "\"labels\": [", "]", next);
        let (_, next) = between(cases, "\"toMeasure\": [", "]", next);
        let (_, next) = between(cases, "\"backgroundMask\": [", "]", next);
        let (regions_text, next) = between(cases, "\"regions\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let labels: Vec<f32> = ints(labels_text).into_iter().map(|v| v as f32).collect();
        let theirs = ints(regions_text);
        assert_eq!(
            labels.len(),
            width * height,
            "{name}: {} labels for {width}x{height}",
            labels.len()
        );

        // The region map only summarises the ROI list faithfully if the filled
        // polygons are disjoint. That is a property of the tracing rather than
        // something the call site promises, so it is recorded and checked here
        // rather than assumed while building the fixture.
        assert_eq!(
            index(overlaps),
            0,
            "{name}: QuPath's filled ROIs overlap, so the region map is lossy \
             and this comparison would be meaningless"
        );

        let mut ours = vec![0u32; labels.len()];
        // `setThreshold(0.5, POSITIVE_INFINITY)` then `Wand.FOUR_CONNECTED`.
        let found = tracer.trace_into(&labels, &mut ours, width, 0.5, f32::INFINITY);

        assert_eq!(
            u64::from(found),
            index(expected_count) as u64,
            "{name}: {found} regions against QuPath's {}",
            index(expected_count)
        );
        for (at, (&ours, &theirs)) in ours.iter().zip(&theirs).enumerate() {
            assert_eq!(
                ours,
                theirs,
                "{name}: at {at} ({}, {}) we trace region {ours}, QuPath traces {theirs}",
                at % width,
                at / width
            );
        }

        println!("{name:>26}  {width:>3}x{height:<3}  {found:>4} regions");
        objects += found;
        count += 1;
    }

    assert!(count >= 17, "only {count} cases in the fixture");

    for (name, why) in [
        (
            "adjacent-labels",
            "the Wand traces a threshold range, not one label",
        ),
        ("ring-with-hole", "the traced polygon fills interior holes"),
        (
            "nested-basin",
            "a basin inside another's hole is discarded, not kept",
        ),
        (
            "diagonal-pinch",
            "background leaves through a corner, so holes are eight-connected",
        ),
        (
            "log-chain",
            "the region count on the input this stage meets in the pipeline",
        ),
    ] {
        assert!(cases.contains(name), "{name} missing: {why} is unchecked");
    }

    println!("{count} label images  {objects} regions, all traced identically");
}
